export default function ({ event }) {
  const $json = JSON.parse(event);
  const body = $json;
  const pick = (...keys) => {
    for (const key of keys) {
      const value = body[key] ?? $json[key];
      if (value !== undefined && value !== null && String(value).trim() !== "")
        return String(value).trim();
    }
    return "";
  };
  const lead = {
    received_at: new Date().toISOString(),
    name: pick("name", "full_name", "contact_name"),
    email: pick("email", "work_email", "business_email").toLowerCase(),
    phone: pick("phone", "mobile", "tel"),
    company: pick("company", "organization", "account"),
    role: pick("role", "job_title", "title"),
    message: pick("message", "details", "project", "notes"),
    budget: pick("budget", "estimated_budget"),
    timeline: pick("timeline", "requested_timeline", "deadline"),
    page_url: pick("page_url", "url", "landing_page", "referrer"),
    source: pick("source", "utm_source") || "website",
    utm_campaign: pick("utm_campaign"),
  };
  const text = `${lead.message} ${lead.budget} ${lead.timeline} ${lead.page_url}`.toLowerCase();
  const tags = [];
  const tagIf = (condition, tag) => {
    if (condition) tags.push(tag);
  };
  tagIf(/demo|book|call|meeting|trial/.test(text), "demo_request");
  tagIf(/pricing|quote|proposal|budget|cost|estimate/.test(text), "commercial_intent");
  tagIf(/urgent|asap|today|tomorrow|this week|deadline/.test(text), "time_sensitive");
  tagIf(
    /integration|api|crm|hubspot|salesforce|zapier|make|n8n|workflow|automation/.test(text),
    "integration_need",
  );
  tagIf(/migration|broken|not working|failed|stuck|error/.test(text), "rescue_need");
  tagIf(/enterprise|security|compliance|sso|soc2|procurement/.test(text), "enterprise_process");
  const contactScore = lead.email.includes("@") ? 20 : lead.phone.length >= 7 ? 12 : 0;
  const companyScore = lead.company ? 10 : 0;
  const roleScore = /founder|owner|ceo|cto|vp|director|head|ops|operations|revops|sales/i.test(
    lead.role,
  )
    ? 10
    : 0;
  const budgetScore = lead.budget ? (/\$|£|€|k|budget|approved/i.test(lead.budget) ? 18 : 8) : 0;
  const tagScore = Math.min(42, tags.length * 7);
  const score = Math.min(
    100,
    contactScore + companyScore + roleScore + budgetScore + tagScore + (lead.page_url ? 5 : 0),
  );
  lead.intent_tags = tags.join(", ") || "general_inquiry";
  lead.lead_score = score;
  lead.priority = score >= 72 ? "hot" : score >= 42 ? "review" : "normal";
  lead.sla_minutes = score >= 72 ? 15 : score >= 42 ? 240 : 1440;
  lead.owner_team = /integration|api|workflow|automation|crm|hubspot|salesforce|make|n8n/.test(text)
    ? "automation_ops"
    : "sales";
  lead.needs_exec_escalation = score >= 82 || /enterprise|procurement|security|sso|soc2/.test(text);
  lead.dedupe_key =
    `${lead.email || lead.phone || "unknown"}:${lead.company || "no-company"}:${lead.page_url || lead.source}`
      .toLowerCase()
      .replace(/\s+/g, "-");
  lead.missing_contact = !(lead.email.includes("@") || lead.phone.length >= 7);
  return { lead, hasContact: !lead.missing_contact };
}

