export default function ({ lead, html }) {
  const title = (html.match(/<title[^>]*>([^<]+)<\/title>/i)?.[1] || "")
    .replace(/\s+/g, " ")
    .trim();
  const desc = (
    html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)/i)?.[1] || ""
  )
    .replace(/\s+/g, " ")
    .trim();
  const pageText = `${title} ${desc}`.toLowerCase();
  const pageTags = [];
  for (const [term, tag] of [
    ["pricing", "pricing_page"],
    ["demo", "demo_page"],
    ["case study", "proof_page"],
    ["integration", "integration_page"],
    ["contact", "contact_page"],
  ]) {
    if (pageText.includes(term)) pageTags.push(tag);
  }
  const pageBoost =
    pageTags.includes("pricing_page") || pageTags.includes("demo_page")
      ? 8
      : pageTags.length
        ? 3
        : 0;
  const score = Math.min(100, Number(lead.lead_score || 0) + pageBoost);
  return {
    lead: {
      ...lead,
      page_title: title,
      page_description: desc,
      page_signal_tags: pageTags.join(", "),
      lead_score: score,
      priority: score >= 72 ? "hot" : score >= 42 ? "review" : "normal",
      sla_minutes: score >= 72 ? 15 : score >= 42 ? 240 : 1440,
    },
  };
}

