export default function ({ lead, hotTo, reviewTo, normalTo, execTo }) {
  const {
    priority,
    lead_score,
    company,
    name,
    email,
    intent_tags,
    sla_minutes,
    owner_team,
    page_url,
    page_signal_tags,
    budget,
    timeline,
    message,
    dedupe_key,
    received_at,
    page_description,
  } = lead;
  let to, subject, body;
  if (priority === "hot") {
    to = hotTo;
    subject = `[HOT ${lead_score}] ${company || name || email} - ${intent_tags}`;
    body = `SLA: ${sla_minutes} minutes\nOwner: ${owner_team}\nTags: ${intent_tags}\nPage: ${page_url}\nPage signals: ${page_signal_tags}\nBudget: ${budget}\nTimeline: ${timeline}\nMessage: ${message}\nDedupe: ${dedupe_key}`;
  } else if (priority === "review") {
    to = reviewTo;
    subject = `[REVIEW ${lead_score}] ${company || name || email}`;
    body = `Review today. Tags: ${intent_tags}\nOwner: ${owner_team}\nMessage: ${message}\nDedupe: ${dedupe_key}`;
  } else {
    to = normalTo;
    subject = `[NORMAL ${lead_score}] ${company || email}`;
    body = `Next business day follow-up. Tags: ${intent_tags}\nMessage: ${message}`;
  }
  return {
    to,
    subject,
    body,
    execTo,
    execSubject: `[EXEC ESCALATION] ${company || email} - score ${lead_score}`,
    execBody: `Enterprise/high-score lead needs fast review.\nOwner: ${owner_team}\nTags: ${intent_tags}\nBudget: ${budget}\nTimeline: ${timeline}\nMessage: ${message}`,
    needsExec: priority === "hot" && lead.needs_exec_escalation,
    values: [
      [
        received_at,
        priority,
        lead_score,
        sla_minutes,
        owner_team,
        intent_tags,
        page_signal_tags,
        dedupe_key,
        email,
        company,
        message,
        name,
        lead.phone,
        lead.role,
        budget,
        timeline,
        page_url,
        lead.source,
        lead.utm_campaign,
        lead.needs_exec_escalation,
        lead.missing_contact,
        lead.page_title,
        page_description,
      ],
    ],
    response: {
      statusCode: 200,
      body: { ok: true, status: priority, score: lead_score, sla_minutes, owner_team, dedupe_key },
    },
  };
}

